/**
 * Object storage for binary files (images today; footage and assets later).
 * PostgreSQL holds metadata only; the bytes live behind this interface.
 *
 * Keys are generated by the server from ids (never from user input) and use
 * the characters [a-z0-9/_-] only, so every driver can map them safely.
 */
export type StoredObject = {
  body: ReadableStream<Uint8Array>;
  size: number;
};

export interface ObjectStorage {
  /** A short name for logs and the health of the configuration ("filesystem", "s3"). */
  readonly driver: string;
  put(key: string, body: Uint8Array, contentType: string): Promise<void>;
  /** Null when the object does not exist. */
  get(key: string): Promise<StoredObject | null>;
  /** Deletes the objects; missing keys are not an error. */
  delete(keys: string[]): Promise<void>;
}

const KEY = /^[a-z0-9][a-z0-9/_-]{0,250}$/;

export function assertValidKey(key: string): void {
  if (!KEY.test(key) || key.includes("//") || key.includes("..")) {
    throw new Error(`Invalid storage key: ${key}`);
  }
}
